# Публичный классификатор: пропускаем идентификаторы и известный шум.
# Объединение правил v5 (сканер_1) и текущих (pages.py).
_IDENTIFIER_RX = [
    # --- базовые идентификаторы ---
    re.compile(r'^[a-f0-9]{7,40}$'),                            # SHA
    re.compile(r'^https?://\S+$'),                              # URL
    re.compile(r'^[\w\-\.]+@[\w\-\.]+$'),                       # email
    re.compile(r'^\d+\.\d+\.\d+\.\d+$'),                        # IP                               # проверка '/' ниже

    # --- размеры ---
    re.compile(r'^\d+(\.\d+)?\s*(B|KB|MB|GB|TB)$'),
    re.compile(r'^\d+(\.\d+)?\s*(B|KB|MB|GB|TB)\s+cached$'),

    # --- длительности ---
    re.compile(r'^\d+m\s*\d+s$'),
    re.compile(r'^\d+(\.\d+)?s$'),

    # --- k-числа ---
    re.compile(r'^-?\d+(\.\d+)?k$'),

    # --- дроби ---
    re.compile(r'^\d+\s*/\s*\d+$'),

    # --- даты ---
    # "Oct 29, 2026, 8:45 AM GMT+3"
    re.compile(r'^\w{3}\s+\d{1,2},\s+\d{4}(,?\s+\d{1,2}:\d{2}\s*(AM|PM)?)?(\s+GMT[+-]\d+)?$'),
    # "Sun, Oct 29, 2026 …"
    re.compile(r'^(Sun|Mon|Tue|Wed|Thu|Fri|Sat)\w*,?\s+\w+\s+\d{1,2},\s+\d{4}.*$'),
    # "10/15, 0. Total." / "10/24, 302. Total."
    re.compile(r'^\d{1,2}/\d{1,2},\s*-?\d+\.\s*(Total|Unique)\.$'),

    # --- placeholder-скелетоны ---
    re.compile(r'^[Xx]{4,}$'),
]


def is_identifier(text: str) -> bool:
    """True, если строку НЕ нужно переводить (идентификатор, шум, число и т.п.)."""
    t = text.strip()
    if not t:
        return True

    # «длинное» слово с '_' или '/' — почти всегда путь/идентификатор
    if '_' in t and len(t) >= 10 and re.fullmatch(r'[\w\-]+', t):
        return True
    if '/' in t and len(t) >= 10 and re.fullmatch(r'[\w\-/]+', t):
        return True

    for rx in _IDENTIFIER_RX:
        if rx.fullmatch(t):
            return True

    return False